package com.aistock.gateway.statistics;
import com.aistock.common.*;import com.aistock.gateway.EngineeringStatusController;import java.time.*;import java.util.concurrent.atomic.AtomicLong;import org.junit.jupiter.api.Test;import org.springframework.web.bind.annotation.*;import org.springframework.test.web.servlet.setup.MockMvcBuilders;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import static org.junit.jupiter.api.Assertions.*;
class HttpStatisticsAccessTest {
 @RestController static class Fixture {
  @GetMapping("/api/v1/instruments/{id}")Object market(){return java.util.Map.of("ok",true);}
  @GetMapping("/api/v1/admin/statistics/http")Object self(){return java.util.Map.of("ok",true);}
  @GetMapping("/api/v1/users/me")Object unexpected(){throw new IllegalStateException("test-internal");}
  @GetMapping("/api/v1/stock-questions")Object failure(){throw new BusinessException("TEST_ERROR","failure",org.springframework.http.HttpStatus.SERVICE_UNAVAILABLE);}
 }
 @Test void recordsMatchedBusinessOnceExcludingStatsAndUnknownPaths()throws Exception{var clock=Clock.fixed(Instant.parse("2026-10-22T00:00:00Z"),ZoneOffset.UTC);var c=new HttpStatisticsCollector(clock.instant(),clock);var ticks=new AtomicLong();var mvc=MockMvcBuilders.standaloneSetup(new Fixture(),new EngineeringStatusController()).setControllerAdvice(new ApiExceptionHandler()).addFilters(new HttpStatisticsFilter(c,()->ticks.getAndAdd(10_000_000))).build();mvc.perform(get("/api/v1/instruments/SH600030")).andExpect(status().isOk());mvc.perform(get("/api/v1/admin/statistics/http")).andExpect(status().isOk());mvc.perform(get("/api/v1/not-real/private-id")).andExpect(status().isNotFound());mvc.perform(get("/api/v1/stock-questions")).andExpect(status().isServiceUnavailable());var s=c.snapshot(clock.instant());assertEquals("2",Long.toString(s.groups().stream().mapToLong(x->Long.parseLong(x.completedRequests())).sum()));assertEquals("1",s.groups().stream().filter(x->x.group().equals("ANALYSIS")).findFirst().orElseThrow().http5xx());}
 @Test void genericExceptionUsesFinal500AndErrorDispatchDoesNotDoubleCount()throws Exception{var clock=Clock.fixed(Instant.parse("2026-10-22T00:00:00Z"),ZoneOffset.UTC);var c=new HttpStatisticsCollector(clock.instant(),clock);var ticks=new AtomicLong();var mvc=MockMvcBuilders.standaloneSetup(new Fixture()).setControllerAdvice(new ApiExceptionHandler()).addFilters(new HttpStatisticsFilter(c,()->ticks.getAndAdd(10_000_000))).build();mvc.perform(get("/api/v1/users/me")).andExpect(status().isInternalServerError());mvc.perform(get("/api/v1/users/me").with(r->{r.setDispatcherType(jakarta.servlet.DispatcherType.ERROR);r.setAttribute(jakarta.servlet.RequestDispatcher.ERROR_REQUEST_URI,"/api/v1/users/me");return r;})).andExpect(status().isInternalServerError());assertEquals("1",c.snapshot(clock.instant()).groups().get(0).http5xx());}
}
